    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { name: value.name, moves: value.moves, elapsedMs: value.elapsedMs };
}

function readMatch(value: unknown): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
    typeof value.boardCode !== 'string' ||
    !Array.isArray(value.players) || value.players.length !== 2 ||
    !Array.isArray(value.results) || value.results.length !== 2
  )
    return null;
  const firstPlayer = playerSlot(value.players[0]);
  const secondPlayer = playerSlot(value.players[1]);
  const firstResult = readResult(value.results[0]);
  const secondResult = readResult(value.results[1]);
  if (
    firstPlayer === undefined || secondPlayer === undefined ||
    firstResult === undefined || secondResult === undefined ||
    (value.winner !== null && typeof value.winner !== 'string')
  )
    return null;
  return {
    boardCode: value.boardCode,
    players: [firstPlayer, secondPlayer],
    results: [firstResult, secondResult],
    winner: value.winner,
  };
}

function readRound(value: unknown): TournamentRound | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['matches', 'name', 'size']) ||
    typeof value.name !== 'string' ||
    typeof value.size !== 'number' ||
    !Array.isArray(value.matches)
  )
    return null;
  const matches = value.matches.map(readMatch);
  if (matches.some((match) => match === null)) return null;
  return { name: value.name as TournamentRound['name'], size: value.size, matches: matches as TournamentMatch[] };
}

function phase(value: unknown): TournamentPhase | null {
  return value === 'ready' || value === 'playing' || value === 'next-turn' || value === 'next-match' || value === 'complete'
    ? value
    : null;
}

function resultFits(result: MatchResult | null, name: string | null, size: number): boolean {
  return result === null || (
    name !== null && result.name === name && isValidPlayerName(result.name) &&
    isNonnegativeSafeInteger(result.moves) && result.moves >= (size * size) / 2 &&
    result.moves <= MOVES_MAX
  );
}

function matchIsFinished(match: TournamentMatch): boolean {
  return match.results[0] !== null && match.results[1] !== null && match.winner !== null;
}

function validateResults(rounds: readonly TournamentRound[], players: readonly string[]): boolean {
  for (const [roundIndex, round] of rounds.entries()) {
    for (const [matchIndex, match] of round.matches.entries()) {
      const [first, second] = match.players;
      const [firstResult, secondResult] = match.results;
      if (
        !resultFits(firstResult, first, round.size) ||
        !resultFits(secondResult, second, round.size) ||
        (match.winner !== null && !players.includes(match.winner))
      )
        return false;
      if ((match.winner === null) !== (firstResult === null || secondResult === null)) return false;
      if (match.winner !== null) {
        if (!first || !second || !firstResult || !secondResult) return false;
        const expected = compareResults(
          firstResult,
          secondResult,
          players.indexOf(first),
          players.indexOf(second),
        ) <= 0 ? first : second;
        if (match.winner !== expected) return false;
      }
      if (roundIndex === 0 && matchIndex > 0 && match.players.some((name) => name === null)) return false;
    }
  }
  return true;
}

function validateProgress(tournament: Tournament, game: GameState | null): boolean {
  const { roundIndex, matchIndex, phase: currentPhase, playerIndex, rounds } = tournament;
  const currentRound = rounds[roundIndex];
  const current = tournamentMatch(tournament);
  if (!currentRound || !current) return false;
  for (const [r, round] of rounds.entries()) {
    for (const [m, match] of round.matches.entries()) {
      const before = r < roundIndex || (r === roundIndex && m < matchIndex);
      const after = r > roundIndex || (r === roundIndex && m > matchIndex);
      if (before && !matchIsFinished(match)) return false;
      if (after && (match.results.some((result) => result !== null) || match.winner !== null)) return false;
    }
  }
  const currentFinished = currentPhase === 'next-match' || currentPhase === 'complete';
  if (currentFinished !== matchIsFinished(current)) return false;
  if (currentPhase === 'next-turn' && (playerIndex !== 0 || !current.results[0] || current.results[1])) return false;
  if ((currentPhase === 'ready' || currentPhase === 'playing') &&
      (playerIndex === 0 ? current.results.some((result) => result !== null) : !current.results[0] || current.results[1]))
    return false;
  if (currentFinished && (playerIndex !== 1 || !current.winner)) return false;
  const isFinalMatch = roundIndex === rounds.length - 1 && matchIndex === currentRound.matches.length - 1;
  if ((currentPhase === 'complete') !== isFinalMatch && currentFinished) return false;
  if (currentPhase === 'playing')
    return game !== null && game.boardCode === current.boardCode && !isWon(game);
  if (currentPhase === 'next-turn' || currentPhase === 'next-match')
    return game !== null && game.boardCode === current.boardCode && isWon(game);
  return game === null;
}

export interface TournamentSetup {
  readonly playerCount: PlayerCount;
  readonly players: readonly string[];
}

export function readSetup(value: unknown): TournamentSetup | null {
  if (!isJsonObject(value) || !hasExactKeys(value, ['playerCount', 'players']) || !Array.isArray(value.players))
    return null;
  const count = playerCount(value.playerCount);
  if (count === null || value.players.length !== 8 || value.players.some((name) => typeof name !== 'string'))
    return null;
  return { playerCount: count, players: value.players as string[] };
}

export function readTournament(value: unknown, game: GameState | null): Tournament | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['matchIndex', 'playerCount', 'playerIndex', 'phase', 'players', 'roundIndex', 'rounds']) ||
    !Array.isArray(value.players) || !Array.isArray(value.rounds)
  )
    return null;
  const count = playerCount(value.playerCount);
  const currentPhase = phase(value.phase);
  if (
    count === null || currentPhase === null || value.players.length !== count ||
    value.players.some((name) => typeof name !== 'string') ||
    !isNonnegativeSafeInteger(value.roundIndex) || !isNonnegativeSafeInteger(value.matchIndex) ||
    (value.playerIndex !== 0 && value.playerIndex !== 1)
  )
    return null;
  const players = value.players as string[];
  const names = validatePlayerNames(players, count);
  if (!names.ok || names.names.some((name, index) => name !== players[index])) return null;
  const rounds = value.rounds.map(readRound);
  if (rounds.some((round) => round === null)) return null;
  const validRounds = rounds as TournamentRound[];
  const codes = validRounds.flatMap((round) => round.matches.map((match) => match.boardCode));
  const expected = createTournament(players, codes);
  if (!expected || validRounds.length !== expected.rounds.length) return null;
  const tournament: Tournament = {
    matchIndex: value.matchIndex,
    playerCount: count,
    playerIndex: value.playerIndex,
    phase: currentPhase,
    players,
    roundIndex: value.roundIndex,
    rounds: validRounds,
  };
  for (const [r, round] of validRounds.entries()) {
    const baseline = expected.rounds[r];
    if (!baseline || round.name !== baseline.name || round.size !== baseline.size || round.matches.length !== baseline.matches.length)
      return null;
    for (const [m, match] of round.matches.entries()) {
      const priorRound = validRounds[r - 1];
      const expectedPlayers = r === 0
        ? baseline.matches[m]?.players
        : [priorRound?.matches[m * 2]?.winner ?? null, priorRound?.matches[m * 2 + 1]?.winner ?? null];
      if (!expectedPlayers || match.players[0] !== expectedPlayers[0] || match.players[1] !== expectedPlayers[1]) return null;
    }
  }
  return validateResults(validRounds, players) && validateProgress(tournament, game) ? tournament : null;
}

