    }
    if (phase === 'complete' && previousPhase.current === 'playing') backButton.current?.focus();
    previousPhase.current = phase;
  }, [game, headingRef, phase, tournament]);

  function start(event: React.FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const checked = validatePlayerNames(draft.players.slice(0, draft.playerCount), draft.playerCount);
    if (!checked.ok) {
      onAnnouncement(checked.error);
      return;
    }
    const players = [...checked.names];
    const accepted: Draft = {
      playerCount: draft.playerCount,
      players: [...players, ...draft.players.slice(players.length)],
    };
    setDraft(accepted);
    focusStart.current = true;
    if (!controller.begin(draft.playerCount, players)) {
      focusStart.current = false;
      onAnnouncement('Could not start tournament.');
    }
  }

  function updateName(index: number, value: string): void {
    const players = [...draft.players];
    players[index] = value;
    setDraft({ ...draft, players });
  }

  function requestLeave(): void {
    setConfirmation('leave');
  }

  function requestLoad(): void {
    const transfer = decodeTournamentTransfer(json);
    if (!transfer) {
      onAnnouncement('Invalid tournament.');
      return;
    }
    if (tournament && phase !== 'complete') {
      pendingTransfer.current = transfer;
      setConfirmation('load');
      return;
    }
    setDraft(transfer.setup);
    controller.load(transfer);
  }

  function confirm(): void {
    dialog.current?.close();
    const action = confirmation;
    setConfirmation(null);
    if (action === 'leave') {
      focusHeading.current = true;
      controller.leave();
    } else if (action === 'load' && pendingTransfer.current) {
      const transfer = pendingTransfer.current;
      pendingTransfer.current = null;
      setDraft(transfer.setup);
      controller.load(transfer);
    }
  }

  function cancel(): void {
    pendingTransfer.current = null;
    setConfirmation(null);
  }

  function exportJson(): void {
    const text = controller.exportTournament(draft);
    if (!text) {
      onAnnouncement('Tournament JSON is too large.');
      return;
    }
    setJson(text);
    onAnnouncement('Tournament exported to JSON box.');
  }

  const champion = tournament?.rounds.at(-1)?.matches[0]?.winner;
  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={headingRef} tabIndex={-1}>Tournament</h2>
      {!tournament ? (
        <form className="tournament-setup" onSubmit={start} noValidate>
          <div className="tournament-player-count">
            <label htmlFor="tournament-player-count">Players</label>
            <select
              id="tournament-player-count"
              className="control"
              value={draft.playerCount}
              onChange={(event) => setDraft({ ...draft, playerCount: Number(event.currentTarget.value) === 8 ? 8 : 4 })}
            >
              <option value="4">4</option>
              <option value="8">8</option>
            </select>
          </div>
          <div className="tournament-player-fields">
            {draft.players.slice(0, draft.playerCount).map((name, index) => (
              <div className="tournament-name-field" key={index}>
                <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
                <input
                  id={`tournament-player-${index + 1}`}
                  className="control"
                  value={name}
                  onChange={(event) => updateName(index, event.currentTarget.value)}
                  aria-describedby="tournament-announcement"
                />
              </div>
            ))}
          </div>
          <button type="submit" className="control">Start tournament</button>
        </form>
      ) : (
        <div className="tournament-active">
          {round && <p className="tournament-round">Round: {round.name}</p>}
          {phase === 'ready' && player && (
            <button ref={startButton} type="button" className="control" onClick={() => {
              focusBoard.current = true;
              controller.startCurrentTurn();
            }}>Start turn</button>
          )}
          {phase === 'next-turn' && (
            <button type="button" className="control" onClick={() => {
              focusStart.current = true;
              controller.advanceTurn();
            }}>Next turn</button>
          )}
          {phase === 'next-match' && (
            <button type="button" className="control" onClick={() => {
              focusStart.current = true;
              controller.advanceMatch();
            }}>Next match</button>
          )}
          {phase === 'complete' && (
            <div className="tournament-champion">
              <h3>Champion: {champion}</h3>
              <button ref={backButton} type="button" className="control" onClick={onBack}>Back to game</button>
            </div>
          )}
          {game && (
            <>
              <dl className="tournament-stats">
                <div><dt>Moves</dt><dd>{game.moves}</dd></div>
                <div><dt>Pairs</dt><dd>{game.matched.length / 2} / {game.deck.length / 2}</dd></div>
                <div><dt>Time</dt><dd>{formatElapsed(game.elapsedMs)}</dd></div>
              </dl>
              {isWon(game) && <p className="tournament-finished">Turn complete.</p>}
              <p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p>
              <Board key={controller.session.generation} game={game} activate={controller.activate} ref={board} />
            </>
          )}
          {tournament && <BracketSummary tournament={tournament} />}
          {tournament && phase !== 'complete' && (
            <button type="button" className="control tournament-leave" onClick={requestLeave}>Leave tournament</button>
          )}
        </div>
      )}
      <section className="tournament-transfer" aria-labelledby="tournament-json-heading">
        <h3 id="tournament-json-heading">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={8}
          maxLength={65_536}
          value={json}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button type="button" className="control" onClick={exportJson}>Export tournament</button>
          <button type="button" className="control" onClick={requestLoad}>Load tournament</button>
        </div>
      </section>
      <TournamentHistory available={controller.history.available} records={controller.history.records} />
      <dialog ref={dialog} className="tournament-dialog" onCancel={cancel}>
        <p>{confirmation === 'leave'
          ? 'Leave this unfinished tournament? Its bracket won’t be saved.'
          : 'Load this tournament and leave the current tournament?'}</p>
        <div className="tournament-actions">
          <button ref={keepButton} type="button" className="control" onClick={() => { dialog.current?.close(); cancel(); }}>
            Keep playing
          </button>
          <button type="button" className="control" onClick={confirm}>
            {confirmation === 'leave' ? 'Leave' : 'Load tournament'}
          </button>
        </div>
      </dialog>
    </section>
  );
}

function BracketSummary({ tournament }: { tournament: NonNullable<ReturnType<typeof useTournament>['session']['tournament']> }) {
  return <TournamentBracket tournament={tournament} />;
}

