            <div><dt>Time</dt><dd>{formatElapsed(game.elapsedMs)}</dd></div>
          </dl>
          {isWon(game) && <p className="tournament-finished">Turn complete.</p>}
          <p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p>
          <Board key={generation} game={game} activate={onActivate} ref={board} />
        </>
      )}
      <Bracket tournament={tournament} />
      {phase !== 'complete' && (
        <button type="button" className="control tournament-leave" onClick={onLeave}>Leave tournament</button>
      )}
    </div>
  );
}

