 23	  readonly playerCount: PlayerCount;
 24	  readonly players: readonly string[];
 25	}
 26	
 27	export function Tournament({ headingRef, onAnnouncement, onBack }: TournamentProps) {
 28	  const [draft, setDraft] = useState<Draft>(() => ({ playerCount: 4, players: Array.from({ length: 8 }, () => '') }));
 29	  const [json, setJson] = useState('');
 30	  const [confirmation, setConfirmation] = useState<'leave' | 'load' | null>(null);
 31	  const controller = useTournament(onAnnouncement);
 32	  const dialog = useRef<HTMLDialogElement | null>(null);
 33	  const keepButton = useRef<HTMLButtonElement | null>(null);
 34	  const backButton = useRef<HTMLButtonElement | null>(null);
 35	  const startButton = useRef<HTMLButtonElement | null>(null);
 36	  const board = useRef<BoardFocus | null>(null);
 37	  const pendingTransfer = useRef<TournamentTransfer | null>(null);
 38	  const focusStart = useRef(false);
 39	  const focusBoard = useRef(false);
 40	  const focusHeading = useRef(false);
 41	  const previousPhase = useRef<TournamentPhase | undefined>(undefined);
 42	  const tournament = controller.session.tournament;
 43	  const game = controller.session.game;
 44	  const phase = tournament?.phase;
 45	  const match = tournament ? tournamentMatch(tournament) : undefined;
 46	  const round = tournament?.rounds[tournament.roundIndex];
 47	  const player = tournament ? tournamentPlayer(tournament) : undefined;
 48	
 49	  useEffect(() => {
 50	    if (!confirmation || !dialog.current) return;
 51	    dialog.current.showModal();
 52	    keepButton.current?.focus();
 53	  }, [confirmation]);
 54	
 55	  useLayoutEffect(() => {
 56	    if (focusHeading.current && !tournament) {
 57	      headingRef.current?.focus();
 58	      focusHeading.current = false;
 59	    }
 60	    if (focusStart.current && phase === 'ready') {
 61	      startButton.current?.focus();
 62	      focusStart.current = false;
 63	    }
 64	    if (focusBoard.current && game) {
 65	      board.current?.focusRemembered();
 66	      focusBoard.current = false;
 67	    }
 68	    if (phase === 'complete' && previousPhase.current === 'playing') backButton.current?.focus();
 69	    previousPhase.current = phase;
 70	  }, [game, headingRef, phase, tournament]);
 71	
 72	  function start(event: React.FormEvent<HTMLFormElement>): void {
 73	    event.preventDefault();
 74	    const checked = validatePlayerNames(draft.players.slice(0, draft.playerCount), draft.playerCount);
 75	    if (!checked.ok) {
 76	      onAnnouncement(checked.error);
 77	      return;
 78	    }
 79	    const players = [...checked.names];
 80	    const accepted: Draft = {
 81	      playerCount: draft.playerCount,
 82	      players: [...players, ...draft.players.slice(players.length)],
 83	    };
 84	    setDraft(accepted);
 85	    focusStart.current = true;
 86	    if (!controller.begin(draft.playerCount, players)) {
 87	      focusStart.current = false;
 88	      onAnnouncement('Could not start tournament.');
 89	    }
 90	  }
 91	
 92	  function updateName(index: number, value: string): void {
 93	    const players = [...draft.players];
 94	    players[index] = value;
 95	    setDraft({ ...draft, players });
 96	  }
 97	
 98	  function requestLeave(): void {
 99	    setConfirmation('leave');
100	  }
101	
102	  function requestLoad(): void {
103	    const transfer = decodeTournamentTransfer(json);
104	    if (!transfer) {
105	      onAnnouncement('Invalid tournament.');
106	      return;
107	    }
108	    if (tournament && phase !== 'complete') {
109	      pendingTransfer.current = transfer;
110	      setConfirmation('load');
111	      return;
112	    }
113	    setDraft(transfer.setup);
114	    controller.load(transfer);
115	  }
116	
117	  function confirm(): void {
118	    dialog.current?.close();
119	    const action = confirmation;
120	    setConfirmation(null);
121	    if (action === 'leave') {
122	      focusHeading.current = true;
123	      controller.leave();
124	    } else if (action === 'load' && pendingTransfer.current) {
125	      const transfer = pendingTransfer.current;
126	      pendingTransfer.current = null;
127	      setDraft(transfer.setup);
128	      controller.load(transfer);
129	    }
130	  }
131	
132	  function cancel(): void {
133	    pendingTransfer.current = null;
134	    setConfirmation(null);
135	  }
136	
137	  function exportJson(): void {
138	    const text = controller.exportTournament(draft);
139	    if (!text) {
140	      onAnnouncement('Tournament JSON is too large.');
141	      return;
142	    }
143	    setJson(text);
144	    onAnnouncement('Tournament exported to JSON box.');
145	  }
146	
147	  const champion = tournament?.rounds.at(-1)?.matches[0]?.winner;
148	  return (
149	    <section className="tournament-screen" aria-labelledby="tournament-heading">
150	      <h2 id="tournament-heading" ref={headingRef} tabIndex={-1}>Tournament</h2>
151	      {!tournament ? (
152	        <form className="tournament-setup" onSubmit={start} noValidate>
153	          <div className="tournament-player-count">
154	            <label htmlFor="tournament-player-count">Players</label>
155	            <select
156	              id="tournament-player-count"
157	              className="control"
158	              value={draft.playerCount}
159	              onChange={(event) => setDraft({ ...draft, playerCount: Number(event.currentTarget.value) === 8 ? 8 : 4 })}
160	            >
161	              <option value="4">4</option>
162	              <option value="8">8</option>
163	            </select>
164	          </div>
165	          <div className="tournament-player-fields">
166	            {draft.players.slice(0, draft.playerCount).map((name, index) => (
167	              <div className="tournament-name-field" key={index}>
168	                <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
169	                <input
170	                  id={`tournament-player-${index + 1}`}
171	                  className="control"
172	                  value={name}
173	                  onChange={(event) => updateName(index, event.currentTarget.value)}
174	                  aria-describedby="tournament-announcement"
175	                />
176	              </div>
177	            ))}
178	          </div>
179	          <button type="submit" className="control">Start tournament</button>
180	        </form>
181	      ) : (
182	        <div className="tournament-active">
183	          {round && <p className="tournament-round">Round: {round.name}</p>}
184	          {phase === 'ready' && player && (
185	            <button ref={startButton} type="button" className="control" onClick={() => {
186	              focusBoard.current = true;
187	              controller.startCurrentTurn();
188	            }}>Start turn</button>
189	          )}
190	          {phase === 'next-turn' && (
191	            <button type="button" className="control" onClick={() => {
192	              focusStart.current = true;
193	              controller.advanceTurn();
194	            }}>Next turn</button>
195	          )}
196	          {phase === 'next-match' && (
197	            <button type="button" className="control" onClick={() => {
198	              focusStart.current = true;
199	              controller.advanceMatch();
200	            }}>Next match</button>
201	          )}
202	          {phase === 'complete' && (
203	            <div className="tournament-champion">
204	              <h3>Champion: {champion}</h3>
205	              <button ref={backButton} type="button" className="control" onClick={onBack}>Back to game</button>
206	            </div>
207	          )}
208	          {game && (
209	            <>
210	              <dl className="tournament-stats">
211	                <div><dt>Moves</dt><dd>{game.moves}</dd></div>
212	                <div><dt>Pairs</dt><dd>{game.matched.length / 2} / {game.deck.length / 2}</dd></div>
213	                <div><dt>Time</dt><dd>{formatElapsed(game.elapsedMs)}</dd></div>
214	              </dl>
215	              {isWon(game) && <p className="tournament-finished">Turn complete.</p>}
216	              <p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p>
217	              <Board key={controller.session.generation} game={game} activate={controller.activate} ref={board} />
218	            </>
219	          )}
220	          {tournament && <BracketSummary tournament={tournament} />}
221	          {tournament && phase !== 'complete' && (
222	            <button type="button" className="control tournament-leave" onClick={requestLeave}>Leave tournament</button>
223	          )}
224	        </div>
225	      )}
226	      <section className="tournament-transfer" aria-labelledby="tournament-json-heading">
227	        <h3 id="tournament-json-heading">Tournament JSON</h3>
228	        <label htmlFor="tournament-json">Tournament JSON</label>
229	        <textarea
230	          id="tournament-json"
231	          className="control"
232	          rows={8}
233	          maxLength={65_536}
234	          value={json}
235	          onChange={(event) => setJson(event.currentTarget.value)}
236	        />
237	        <div className="tournament-actions">
238	          <button type="button" className="control" onClick={exportJson}>Export tournament</button>
239	          <button type="button" className="control" onClick={requestLoad}>Load tournament</button>
240	        </div>
241	      </section>
242	      <TournamentHistory available={controller.history.available} records={controller.history.records} />
243	      <dialog ref={dialog} className="tournament-dialog" onCancel={cancel}>
244	        <p>{confirmation === 'leave'
245	          ? 'Leave this unfinished tournament? Its bracket won’t be saved.'
246	          : 'Load this tournament and leave the current tournament?'}</p>
247	        <div className="tournament-actions">
248	          <button ref={keepButton} type="button" className="control" onClick={() => { dialog.current?.close(); cancel(); }}>
249	            Keep playing
250	          </button>
251	          <button type="button" className="control" onClick={confirm}>
252	            {confirmation === 'leave' ? 'Leave' : 'Load tournament'}
253	          </button>
254	        </div>
255	      </dialog>
256	    </section>
257	  );
258	}
259	
260	function BracketSummary({ tournament }: { tournament: NonNullable<ReturnType<typeof useTournament>['session']['tournament']> }) {
261	  return <TournamentBracket tournament={tournament} />;
262	}
