    return {
      ...tournament,
      phase: 'next-turn',
      rounds: replaceMatch(tournament.rounds, tournament.roundIndex, tournament.matchIndex, { ...match, results }),
    };
  }
  const first = results[0];
  const second = results[1];
  const firstName = match.players[0];
  const secondName = match.players[1];
