function replaceMatch(
  rounds: readonly TournamentRound[],
  roundIndex: number,
  matchIndex: number,
  match: TournamentMatch,
): readonly TournamentRound[] {
  return rounds.map((round, index) =>
    index === roundIndex
      ? { ...round, matches: round.matches.map((entry, itemIndex) => itemIndex === matchIndex ? match : entry) }
