import { useRef, useState } from 'react';
import { activateCard, createGame, isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { useGameClock } from '../session/use-game-clock.ts';
import { encodeTournamentTransfer } from './format.ts';
import type { TournamentTransfer } from './format.ts';
import type { TournamentSetup } from './format-validation.ts';
import { browserTournamentStore, readTournamentHistory, writeTournamentHistory } from './storage.ts';
import { createTournament, tournamentDealSizes } from './pairing.ts';
import { finishTurn, nextMatch, nextTurn, startTurn, tournamentMatch, tournamentPlayer } from './rules.ts';
import { completedSetup, emptyTournamentSession, tickTournament } from './tournament-session.ts';
import type { TournamentStore, TournamentHistory } from './storage.ts';
import type { Tournament } from './rules.ts';
import type { PlayerCount } from './rules.ts';
import type { TournamentSession } from './tournament-session.ts';

export function useTournament(announce: (message: string) => void) {
  const [store] = useState<TournamentStore | null>(browserTournamentStore);
  const [history, setHistory] = useState<TournamentHistory>(() => readTournamentHistory(store));
  const [session, setSession] = useState(emptyTournamentSession);
  const current = useRef(session);

  function commit(next: TournamentSession): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useGameClock(session, current, commit, tickTournament);

  function saveCompleted(tournament: Tournament): void {
    const record: TournamentTransfer = { setup: completedSetup(tournament), tournament, game: null };
    const records = [record, ...history.records].slice(0, 10);
    setHistory({ available: writeTournamentHistory(store, records), records });
  }

  function begin(playerCount: PlayerCount, players: readonly string[]): boolean {
    const codes: string[] = [];
    const used = new Set<string>();
    for (const size of tournamentDealSizes(playerCount)) {
      let code = freshBoardCode(size);
      while (used.has(code)) code = freshBoardCode(size);
      used.add(code);
      codes.push(code);
    }
    const tournament = createTournament(players, codes);
    if (!tournament) return false;
    clock.reset();
    commit({ ...emptyTournamentSession(current.current.generation + 1), tournament });
    const name = tournamentPlayer(tournament);
    if (name) announce(`Now playing: ${name}`);
    return true;
  }

  function startCurrentTurn(): void {
    const latest = current.current;
    const tournament = latest.tournament;
    if (!tournament || tournament.phase !== 'ready') return;
    const match = tournamentMatch(tournament);
    if (!match) return;
    clock.reset();
    commit({
      ...latest,
      game: createGame(match.boardCode),
      generation: latest.generation + 1,
      tournament: startTurn(tournament),
    });
  }

  function activate(index: number): void {
    clock.synchronize();
    const latest = current.current;
    const tournament = latest.tournament;
    if (!tournament || tournament.phase !== 'playing' || !latest.game) return;
    const game = activateCard(latest.game, index);
    if (game === latest.game) return;
    const finished = isWon(game);
    const next = finished ? finishTurn(tournament, game) : tournament;
    const final = next.phase === 'complete';
    commit({ ...latest, game: final ? null : game, tournament: next });
    if (finished) {
      const player = tournamentPlayer(tournament) ?? 'Player';
      const summary = `${player} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`;
      const match = tournamentMatch(next);
      announce(next.phase === 'next-match'
        ? `${summary} ${match?.winner ?? 'The match winner'} wins the match.`
        : final
          ? `${summary} Champion: ${next.rounds.at(-1)?.matches[0]?.winner ?? player}.`
          : summary);
      if (final) saveCompleted(next);
    }
  }

  function advanceTurn(): void {
    const tournament = current.current.tournament;
    if (!tournament) return;
    const next = nextTurn(tournament);
    if (next === tournament) return;
    clock.reset();
    commit({ ...current.current, game: null, generation: current.current.generation + 1, tournament: next });
    const name = tournamentPlayer(next);
    if (name) announce(`Now playing: ${name}`);
  }

  function advanceMatch(): void {
    const tournament = current.current.tournament;
    if (!tournament) return;
    const next = nextMatch(tournament);
    if (next === tournament) return;
    clock.reset();
    commit({ ...current.current, game: null, generation: current.current.generation + 1, tournament: next });
    const name = tournamentPlayer(next);
    const round = next.rounds[next.roundIndex]?.name;
    if (name) announce(`${round ? `Round: ${round}. ` : ''}Now playing: ${name}`);
  }

  function leave(): void {
    clock.reset();
    commit(emptyTournamentSession(current.current.generation + 1));
    announce('Tournament left.');
  }

  function load(transfer: TournamentTransfer): void {
    clock.reset();
    const next: TournamentSession = {
      game: transfer.game,
      generation: current.current.generation + 1,
      paused: false,
      tournament: transfer.tournament,
    };
    commit(next);
    if (transfer.tournament?.phase === 'complete') saveCompleted(transfer.tournament);
    const tournament = transfer.tournament;
    const name = tournament ? tournamentPlayer(tournament) : undefined;
    announce(tournament?.phase === 'ready' || tournament?.phase === 'playing'
      ? `Now playing: ${name ?? 'Player'}`
      : tournament?.phase === 'complete'
        ? `Champion: ${tournament.rounds.at(-1)?.matches[0]?.winner ?? 'Unknown'}`
        : tournament?.phase === 'next-turn'
          ? 'Select Next turn to continue.'
          : tournament?.phase === 'next-match'
            ? 'Select Next match to continue.'
            : 'Tournament loaded.');
  }

  function exportTournament(setup: TournamentSetup): string | null {
    clock.synchronize();
    return encodeTournamentTransfer(setup, current.current.tournament, current.current.game);
  }

  return {
    activate,
    advanceMatch,
    advanceTurn,
    begin,
    exportTournament,
    history,
    leave,
    load,
    session,
    startCurrentTurn,
  };
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { TournamentHistory } from './TournamentHistory.tsx';
import { decodeTournamentTransfer } from './format.ts';
import { firstUnknownTournamentField } from './format-unknown-field.ts';
import { validatePlayerNames } from './names.ts';
import { TournamentPlay } from './TournamentPlay.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { useTournament } from './use-tournament.ts';
import type { FormEvent, RefObject } from 'react';
import type { BoardFocus } from '../board/Board.tsx';
import type { TournamentTransfer } from './format.ts';
import type { TournamentDraft } from './TournamentSetup.tsx';
import type { TournamentPhase } from './rules.ts';
import './tournament.css';

interface TournamentProps {
  headingRef: RefObject<HTMLHeadingElement | null>;
  onAnnouncement(message: string): void;
  onBack(): void;
}

export function Tournament({ headingRef, onAnnouncement, onBack }: TournamentProps) {
  const [draft, setDraft] = useState<TournamentDraft>(() => ({ playerCount: 4, players: Array.from({ length: 8 }, () => '') }));
  const [json, setJson] = useState('');
  const [confirmation, setConfirmation] = useState<'leave' | 'load' | null>(null);
  const controller = useTournament(onAnnouncement);
  const dialog = useRef<HTMLDialogElement | null>(null);
  const keepButton = useRef<HTMLButtonElement | null>(null);
  const backButton = useRef<HTMLButtonElement | null>(null);
  const startButton = useRef<HTMLButtonElement | null>(null);
  const board = useRef<BoardFocus | null>(null);
  const pendingTransfer = useRef<TournamentTransfer | null>(null);
  const focusStart = useRef(false);
  const focusBoard = useRef(false);
  const focusHeading = useRef(false);
  const previousPhase = useRef<TournamentPhase | undefined>(undefined);
  const tournament = controller.session.tournament;
  const phase = tournament?.phase;

  useEffect(() => {
    if (!confirmation || !dialog.current) return;
    dialog.current.showModal();
    keepButton.current?.focus();
  }, [confirmation]);

  useLayoutEffect(() => {
    if (focusHeading.current && !tournament) {
      headingRef.current?.focus();
      focusHeading.current = false;
    }
    if (focusStart.current && phase === 'ready') {
      startButton.current?.focus();
      focusStart.current = false;
    }
    if (focusBoard.current && controller.session.game) {
      board.current?.focusRemembered();
      focusBoard.current = false;
    }
    if (phase === 'complete' && previousPhase.current === 'playing') backButton.current?.focus();
    previousPhase.current = phase;
  }, [controller.session.game, headingRef, phase, tournament]);

  function start(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const checked = validatePlayerNames(draft.players.slice(0, draft.playerCount), draft.playerCount);
    if (!checked.ok) {
      onAnnouncement(checked.error);
      return;
    }
    const players = [...checked.names];
    setDraft({ playerCount: draft.playerCount, players: [...players, ...draft.players.slice(players.length)] });
    focusStart.current = true;
    if (!controller.begin(draft.playerCount, players)) {
      focusStart.current = false;
      onAnnouncement('Could not start tournament.');
    }
  }

  function requestLoad(): void {
    const unknown = firstUnknownTournamentField(json);
    if (unknown) {
      onAnnouncement(`Unknown field: ${unknown}.`);
      return;
    }
    const transfer = decodeTournamentTransfer(json);
    if (!transfer) {
      onAnnouncement('Invalid tournament.');
      return;
    }
    if (tournament && phase !== 'complete') {
      pendingTransfer.current = transfer;
      setConfirmation('load');
      return;
    }
    setDraft(transfer.setup);
    controller.load(transfer);
  }

  function confirm(): void {
    dialog.current?.close();
    const action = confirmation;
    setConfirmation(null);
    if (action === 'leave') {
      focusHeading.current = true;
      controller.leave();
    } else if (action === 'load' && pendingTransfer.current) {
      const transfer = pendingTransfer.current;
      pendingTransfer.current = null;
      setDraft(transfer.setup);
      controller.load(transfer);
    }
  }

  function cancel(): void {
    pendingTransfer.current = null;
    setConfirmation(null);
  }

  function exportJson(): void {
    const text = controller.exportTournament(draft);
    if (!text) {
      onAnnouncement('Tournament JSON is too large.');
      return;
    }
    setJson(text);
    onAnnouncement('Tournament exported to JSON box.');
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={headingRef} tabIndex={-1}>Tournament</h2>
      {tournament ? (
        <TournamentPlay
          tournament={tournament}
          game={controller.session.game}
          generation={controller.session.generation}
          board={board}
          startButton={startButton}
          backButton={backButton}
          onActivate={controller.activate}
          onStartTurn={() => { focusBoard.current = true; controller.startCurrentTurn(); }}
          onNextTurn={() => { focusStart.current = true; controller.advanceTurn(); }}
          onNextMatch={() => { focusStart.current = true; controller.advanceMatch(); }}
          onLeave={() => setConfirmation('leave')}
          onBack={onBack}
        />
      ) : (
        <TournamentSetup draft={draft} onChange={setDraft} onStart={start} />
      )}
      <section className="tournament-transfer" aria-labelledby="tournament-json-heading">
        <h3 id="tournament-json-heading">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea id="tournament-json" className="control" rows={8} maxLength={65_536} value={json}
          onChange={(event) => setJson(event.currentTarget.value)} />
        <div className="tournament-actions">
          <button type="button" className="control" onClick={exportJson}>Export tournament</button>
          <button type="button" className="control" onClick={requestLoad}>Load tournament</button>
        </div>
      </section>
      <TournamentHistory available={controller.history.available} records={controller.history.records} />
      <dialog ref={dialog} className="tournament-dialog" onCancel={cancel}>
        <p>{confirmation === 'leave'
          ? 'Leave this unfinished tournament? Its bracket won’t be saved.'
          : 'Load this tournament and leave the current tournament?'}</p>
        <div className="tournament-actions">
          <button ref={keepButton} type="button" className="control" onClick={() => { dialog.current?.close(); cancel(); }}>
            Keep playing
          </button>
          <button type="button" className="control" onClick={confirm}>
            {confirmation === 'leave' ? 'Leave' : 'Load tournament'}
          </button>
        </div>
      </dialog>
    </section>
  );
}

import { decodeSnapshot, SNAPSHOT_VERSION } from '../snapshot.ts';
import { isWithinBytes, hasExactKeys, isJsonObject, parseJson } from '../saved-format.ts';
import { SelectionKind } from '../selection.ts';
import { readSetup, readTournament } from './format-validation.ts';
import { normalizePlayerName } from './names.ts';
import type { TournamentSetup } from './format-validation.ts';
import type { GameState } from '../game.ts';
import type { Tournament } from './rules.ts';

const FORMAT = 'neon-pairs/tournament';
const VERSION = 1;
const MAX_BYTES = 65_536;

export interface TournamentTransfer {
  readonly game: GameState | null;
  readonly setup: TournamentSetup;
  readonly tournament: Tournament | null;
}

function selectionRecord(game: GameState) {
  switch (game.selection.kind) {
    case SelectionKind.closed:
      return { kind: SelectionKind.closed };
    case SelectionKind.one:
      return { index: game.selection.index, kind: SelectionKind.one };
    case SelectionKind.mismatch:
      return {
        first: game.selection.first,
        kind: SelectionKind.mismatch,
        remainingMs: Math.ceil(game.selection.remainingMs),
        second: game.selection.second,
      };
  }
}

function gameRecord(game: GameState | null) {
  if (!game) return null;
  return {
    boardCode: game.boardCode,
    elapsedMs: Math.floor(game.elapsedMs),
    matched: [...game.matched].sort((a, b) => a - b),
    moves: game.moves,
    selection: selectionRecord(game),
    started: game.started,
    version: SNAPSHOT_VERSION,
  };
}

function tournamentRecord(tournament: Tournament | null) {
  if (!tournament) return null;
  return {
    matchIndex: tournament.matchIndex,
    playerCount: tournament.playerCount,
    playerIndex: tournament.playerIndex,
    phase: tournament.phase,
    players: [...tournament.players],
    roundIndex: tournament.roundIndex,
    rounds: tournament.rounds.map((round) => ({
      matches: round.matches.map((match) => ({
        boardCode: match.boardCode,
        players: [...match.players],
        results: match.results.map((result) => result ? {
          elapsedMs: result.elapsedMs,
          moves: result.moves,
          name: result.name,
        } : null),
        winner: match.winner,
      })),
      name: round.name,
      size: round.size,
    })),
  };
}

export function encodeTournamentTransfer(
  setup: TournamentSetup,
  tournament: Tournament | null,
  game: GameState | null,
): string | null {
  const text = JSON.stringify(
    {
      format: FORMAT,
      game: gameRecord(game),
      setup: { playerCount: setup.playerCount, players: [...setup.players] },
      tournament: tournamentRecord(tournament),
      version: VERSION,
    },
    null,
    2,
  );
  return isWithinBytes(text, MAX_BYTES) ? text : null;
}

export function decodeTournamentTransfer(text: string): TournamentTransfer | null {
  const value = isWithinBytes(text, MAX_BYTES) ? parseJson(text) : undefined;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['format', 'game', 'setup', 'tournament', 'version']) ||
    value.format !== FORMAT || value.version !== VERSION
  )
    return null;
  const setup = readSetup(value.setup);
  if (!setup) return null;
  const game = value.game === null
    ? null
    : isJsonObject(value.game)
      ? decodeSnapshot(JSON.stringify(value.game))
      : null;
  if (value.game !== null && !game) return null;
  const tournament = value.tournament === null ? null : readTournament(value.tournament, game);
  if (value.tournament !== null && !tournament) return null;
  if (!tournament && game) return null;
  if (tournament) {
    const names = setup.players.slice(0, setup.playerCount).map(normalizePlayerName);
    if (setup.playerCount !== tournament.playerCount || names.some((name, index) => name !== tournament.players[index]))
      return null;
  }
  return { setup, tournament, game };
}

import { isWon } from '../game.ts';
import type { GameState } from '../game.ts';

export type PlayerCount = 4 | 8;
export type RoundName = 'Quarterfinal' | 'Semifinal' | 'Final';
export type TournamentPhase = 'ready' | 'playing' | 'next-turn' | 'next-match' | 'complete';

export interface MatchResult {
  readonly elapsedMs: number;
  readonly moves: number;
  readonly name: string;
}

export interface TournamentMatch {
  readonly boardCode: string;
  readonly players: readonly [string | null, string | null];
  readonly results: readonly [MatchResult | null, MatchResult | null];
  readonly winner: string | null;
}

export interface TournamentRound {
  readonly matches: readonly TournamentMatch[];
  readonly name: RoundName;
  readonly size: number;
}

export interface Tournament {
  readonly matchIndex: number;
  readonly playerCount: PlayerCount;
  readonly playerIndex: 0 | 1;
  readonly phase: TournamentPhase;
  readonly players: readonly string[];
  readonly roundIndex: number;
  readonly rounds: readonly TournamentRound[];
}

export function tournamentMatch(tournament: Tournament): TournamentMatch | undefined {
  return tournament.rounds[tournament.roundIndex]?.matches[tournament.matchIndex];
}

export function tournamentPlayer(tournament: Tournament): string | undefined {
  return tournamentMatch(tournament)?.players[tournament.playerIndex] ?? undefined;
}

export function startTurn(tournament: Tournament): Tournament {
  return tournament.phase === 'ready' && tournamentMatch(tournament)?.players[tournament.playerIndex]
    ? { ...tournament, phase: 'playing' }
    : tournament;
}

export function compareResults(left: MatchResult, right: MatchResult, leftSeed: number, rightSeed: number): number {
  if (left.moves !== right.moves) return left.moves < right.moves ? -1 : 1;
  if (left.elapsedMs !== right.elapsedMs) return left.elapsedMs < right.elapsedMs ? -1 : 1;
  return leftSeed > rightSeed ? -1 : leftSeed < rightSeed ? 1 : 0;
}

export function finishTurn(tournament: Tournament, game: GameState): Tournament {
  if (tournament.phase !== 'playing' || !isWon(game)) return tournament;
  const round = tournament.rounds[tournament.roundIndex];
  const match = tournamentMatch(tournament);
  const name = tournamentPlayer(tournament);
  if (!round || !match || !name) return tournament;
  const results: [MatchResult | null, MatchResult | null] = [match.results[0], match.results[1]];
  results[tournament.playerIndex] = { elapsedMs: game.elapsedMs, moves: game.moves, name };
  if (tournament.playerIndex === 0) {
    return {
      ...tournament,
      phase: 'next-turn',
      rounds: replaceMatch(tournament.rounds, tournament.roundIndex, tournament.matchIndex, { ...match, results }),
    };
  }
  const first = results[0];
  const second = results[1];
  const firstName = match.players[0];
  const secondName = match.players[1];
  if (!first || !second || !firstName || !secondName) return tournament;
  const winner = compareResults(first, second, tournament.players.indexOf(firstName), tournament.players.indexOf(secondName)) <= 0
    ? firstName
    : secondName;
  let rounds = replaceMatch(tournament.rounds, tournament.roundIndex, tournament.matchIndex, { ...match, results, winner });
  const finalMatch = tournament.roundIndex === rounds.length - 1 && tournament.matchIndex === round.matches.length - 1;
  if (!finalMatch) {
    const targetRound = rounds[tournament.roundIndex + 1];
    if (targetRound) {
      const targetIndex = Math.floor(tournament.matchIndex / 2);
      const target = targetRound.matches[targetIndex];
      if (target) {
        const players: [string | null, string | null] = [target.players[0], target.players[1]];
        players[tournament.matchIndex % 2] = winner;
        rounds = replaceMatch(rounds, tournament.roundIndex + 1, targetIndex, { ...target, players });
      }
    }
    return { ...tournament, phase: 'next-match', rounds, roundIndex: tournament.roundIndex, matchIndex: tournament.matchIndex };
  }
  return { ...tournament, phase: 'complete', rounds };
}

function replaceMatch(
  rounds: readonly TournamentRound[],
  roundIndex: number,
  matchIndex: number,
  match: TournamentMatch,
): readonly TournamentRound[] {
  return rounds.map((round, index) =>
    index === roundIndex
      ? { ...round, matches: round.matches.map((entry, itemIndex) => itemIndex === matchIndex ? match : entry) }
      : round,
  );
}

export function nextTurn(tournament: Tournament): Tournament {
  return tournament.phase === 'next-turn'
    ? { ...tournament, phase: 'ready', playerIndex: 1 }
    : tournament;
}

export function nextMatch(tournament: Tournament): Tournament {
  if (tournament.phase !== 'next-match') return tournament;
  const round = tournament.rounds[tournament.roundIndex];
  if (!round) return tournament;
  const atEnd = tournament.matchIndex === round.matches.length - 1;
  return atEnd
    ? { ...tournament, phase: 'ready', roundIndex: tournament.roundIndex + 1, matchIndex: 0, playerIndex: 0 }
    : { ...tournament, phase: 'ready', matchIndex: tournament.matchIndex + 1, playerIndex: 0 };
}

import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { ELAPSED_MAX_MS } from '../game.ts';
import { validatePlayerNames } from './names.ts';
import { createTournament } from './pairing.ts';
import { validateTournamentProgress } from './format-progress.ts';
import type { MatchResult, PlayerCount, RoundName, Tournament, TournamentMatch, TournamentPhase, TournamentRound } from './rules.ts';
import type { GameState } from '../game.ts';

function playerCount(value: unknown): PlayerCount | null {
  return value === 4 || value === 8 ? value : null;
}

function playerSlot(value: unknown): string | null | undefined {
  if (value === null || typeof value === 'string') return value;
  return undefined;
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function roundName(value: unknown): RoundName | null {
  return value === 'Quarterfinal' || value === 'Semifinal' || value === 'Final' ? value : null;
}

function readResult(value: unknown): MatchResult | null | undefined {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['elapsedMs', 'moves', 'name']) ||
    typeof value.name !== 'string' ||
    !isNonnegativeSafeInteger(value.moves) ||
    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { name: value.name, moves: value.moves, elapsedMs: value.elapsedMs };
}

function readMatch(value: unknown): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
    typeof value.boardCode !== 'string' ||
    !Array.isArray(value.players) || value.players.length !== 2 ||
    !Array.isArray(value.results) || value.results.length !== 2
  )
    return null;
  const firstPlayer = playerSlot(value.players[0]);
  const secondPlayer = playerSlot(value.players[1]);
  const firstResult = readResult(value.results[0]);
  const secondResult = readResult(value.results[1]);
  if (
    firstPlayer === undefined || secondPlayer === undefined ||
    firstResult === undefined || secondResult === undefined ||
    (value.winner !== null && typeof value.winner !== 'string')
  )
    return null;
  return {
    boardCode: value.boardCode,
    players: [firstPlayer, secondPlayer],
    results: [firstResult, secondResult],
    winner: value.winner,
  };
}

function readRound(value: unknown): TournamentRound | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['matches', 'name', 'size']) ||
    typeof value.name !== 'string' ||
    typeof value.size !== 'number' ||
    !Array.isArray(value.matches)
  )
    return null;
  const name = roundName(value.name);
  if (!name) return null;
  const matches: TournamentMatch[] = [];
  for (const entry of value.matches) {
    const match = readMatch(entry);
    if (!match) return null;
    matches.push(match);
  }
  return { name, size: value.size, matches };
}

function phase(value: unknown): TournamentPhase | null {
  return value === 'ready' || value === 'playing' || value === 'next-turn' || value === 'next-match' || value === 'complete'
    ? value
    : null;
}

export interface TournamentSetup {
  readonly playerCount: PlayerCount;
  readonly players: readonly string[];
}

export function readSetup(value: unknown): TournamentSetup | null {
  if (!isJsonObject(value) || !hasExactKeys(value, ['playerCount', 'players']) || !isStringArray(value.players))
    return null;
  const count = playerCount(value.playerCount);
  if (count === null || value.players.length !== 8)
    return null;
  return { playerCount: count, players: value.players };
}

export function readTournament(value: unknown, game: GameState | null): Tournament | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['matchIndex', 'playerCount', 'playerIndex', 'phase', 'players', 'roundIndex', 'rounds']) ||
    !isStringArray(value.players) || !Array.isArray(value.rounds)
  )
    return null;
  const count = playerCount(value.playerCount);
  const currentPhase = phase(value.phase);
  if (
    count === null || currentPhase === null || value.players.length !== count ||
    !isNonnegativeSafeInteger(value.roundIndex) || !isNonnegativeSafeInteger(value.matchIndex) ||
    (value.playerIndex !== 0 && value.playerIndex !== 1)
  )
    return null;
  const players = value.players;
  const names = validatePlayerNames(players, count);
  if (!names.ok || names.names.some((name, index) => name !== players[index])) return null;
  const validRounds: TournamentRound[] = [];
  for (const entry of value.rounds) {
    const round = readRound(entry);
    if (!round) return null;
    validRounds.push(round);
  }
  const codes = validRounds.flatMap((round) => round.matches.map((match) => match.boardCode));
  const expected = createTournament(players, codes);
  if (!expected || validRounds.length !== expected.rounds.length) return null;
  const tournament: Tournament = {
    matchIndex: value.matchIndex,
    playerCount: count,
    playerIndex: value.playerIndex,
    phase: currentPhase,
    players,
    roundIndex: value.roundIndex,
    rounds: validRounds,
  };
  for (const [r, round] of validRounds.entries()) {
    const baseline = expected.rounds[r];
    if (!baseline || round.name !== baseline.name || round.size !== baseline.size || round.matches.length !== baseline.matches.length)
      return null;
    for (const [m, match] of round.matches.entries()) {
      const priorRound = validRounds[r - 1];
      const expectedPlayers = r === 0
        ? baseline.matches[m]?.players
        : [priorRound?.matches[m * 2]?.winner ?? null, priorRound?.matches[m * 2 + 1]?.winner ?? null];
      if (!expectedPlayers || match.players[0] !== expectedPlayers[0] || match.players[1] !== expectedPlayers[1]) return null;
    }
  }
  return validateTournamentProgress(tournament, game) ? tournament : null;
}

import { hasExactKeys, isJsonObject, parseJson } from '../saved-format.ts';
import { decodeTournamentTransfer, encodeTournamentTransfer } from './format.ts';
import type { TournamentTransfer } from './format.ts';

const HISTORY_KEY = 'np3:tournaments';
const HISTORY_VERSION = 3;
const HISTORY_LIMIT = 10;

export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export interface TournamentHistory {
  readonly available: boolean;
  readonly records: readonly TournamentTransfer[];
}

export function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistory {
  if (!store) return { available: false, records: [] };
  try {
    const text = store.getItem(HISTORY_KEY);
    if (!text) return { available: true, records: [] };
    const value = parseJson(text);
    if (
      !isJsonObject(value) || !hasExactKeys(value, ['items', 'v']) || value.v !== HISTORY_VERSION ||
      !Array.isArray(value.items) || value.items.length > HISTORY_LIMIT
    )
      return { available: true, records: [] };
    const records: TournamentTransfer[] = [];
    for (const item of value.items) {
      if (!isJsonObject(item)) return { available: true, records: [] };
      const record = decodeTournamentTransfer(JSON.stringify(item));
      if (!record?.tournament || record.tournament.phase !== 'complete' || record.game !== null)
        return { available: true, records: [] };
      records.push(record);
    }
    return { available: true, records: records.slice(0, HISTORY_LIMIT) };
  } catch {
    return { available: false, records: [] };
  }
}

export function writeTournamentHistory(
  store: TournamentStore | null,
  records: readonly TournamentTransfer[],
): boolean {
  if (!store) return false;
  try {
    const items: Record<string, unknown>[] = [];
    for (const record of records.slice(0, HISTORY_LIMIT)) {
      const text = encodeTournamentTransfer(record.setup, record.tournament, null);
      const value: unknown = text ? parseJson(text) : undefined;
      if (!isJsonObject(value)) return false;
      items.push(value);
    }
    store.setItem(HISTORY_KEY, JSON.stringify({ v: HISTORY_VERSION, items }));
    return true;
  } catch {
    return false;
  }
}

