  4	import { firstUnknownTournamentField } from './format-unknown-field.ts';
  5	import { validatePlayerNames } from './names.ts';
  6	import { TournamentPlay } from './TournamentPlay.tsx';
  7	import { TournamentSetup } from './TournamentSetup.tsx';
  8	import { useTournament } from './use-tournament.ts';
  9	import type { FormEvent, RefObject } from 'react';
 10	import type { BoardFocus } from '../board/Board.tsx';
 11	import type { TournamentTransfer } from './format.ts';
 12	import type { TournamentDraft } from './TournamentSetup.tsx';
 13	import type { TournamentPhase } from './rules.ts';
 14	import './tournament.css';
 15	
 16	interface TournamentProps {
 17	  headingRef: RefObject<HTMLHeadingElement | null>;
 18	  onAnnouncement(message: string): void;
 19	  onBack(): void;
 20	}
 21	
 22	export function Tournament({ headingRef, onAnnouncement, onBack }: TournamentProps) {
 23	  const [draft, setDraft] = useState<TournamentDraft>(() => ({
 24	    playerCount: 4,
 25	    players: Array.from({ length: 8 }, () => ''),
 26	  }));
 27	  const [json, setJson] = useState('');
 28	  const [confirmation, setConfirmation] = useState<'leave' | 'load' | null>(null);
 29	  const controller = useTournament(onAnnouncement);
 30	  const dialog = useRef<HTMLDialogElement | null>(null);
 31	  const keepButton = useRef<HTMLButtonElement | null>(null);
 32	  const backButton = useRef<HTMLButtonElement | null>(null);
 33	  const startButton = useRef<HTMLButtonElement | null>(null);
 34	  const board = useRef<BoardFocus | null>(null);
 35	  const pendingTransfer = useRef<TournamentTransfer | null>(null);
 36	  const focusStart = useRef(false);
 37	  const focusBoard = useRef(false);
 38	  const focusHeading = useRef(false);
 39	  const previousPhase = useRef<TournamentPhase | undefined>(undefined);
 40	  const tournament = controller.session.tournament;
 41	  const phase = tournament?.phase;
 42	
 43	  useEffect(() => {
 44	    if (!confirmation || !dialog.current) return;
 45	    dialog.current.showModal();
 46	    keepButton.current?.focus();
 47	  }, [confirmation]);
 48	
 49	  useLayoutEffect(() => {
 50	    if (focusHeading.current && !tournament) {
 51	      headingRef.current?.focus();
 52	      focusHeading.current = false;
 53	    }
 54	    if (focusStart.current && phase === 'ready') {
 55	      startButton.current?.focus();
 56	      focusStart.current = false;
 57	    }
 58	    if (focusBoard.current && controller.session.game) {
 59	      board.current?.focusRemembered();
 60	      focusBoard.current = false;
 61	    }
 62	    if (phase === 'complete' && previousPhase.current === 'playing') backButton.current?.focus();
 63	    previousPhase.current = phase;
 64	  }, [controller.session.game, headingRef, phase, tournament]);
 65	
 66	  function start(event: FormEvent<HTMLFormElement>): void {
 67	    event.preventDefault();
 68	    const checked = validatePlayerNames(
 69	      draft.players.slice(0, draft.playerCount),
 70	      draft.playerCount,
 71	    );
 72	    if (!checked.ok) {
 73	      onAnnouncement(checked.error);
 74	      return;
 75	    }
 76	    const players = [...checked.names];
 77	    setDraft({
 78	      playerCount: draft.playerCount,
 79	      players: [...players, ...draft.players.slice(players.length)],
 80	    });
 81	    focusStart.current = true;
 82	    if (!controller.begin(draft.playerCount, players)) {
 83	      focusStart.current = false;
 84	      onAnnouncement('Could not start tournament.');
 85	    }
 86	  }
 87	
 88	  function requestLoad(): void {
 89	    const unknown = firstUnknownTournamentField(json);
 90	    if (unknown) {
 91	      onAnnouncement(`Unknown field: ${unknown}.`);
