111	    setConfirmation(null);
112	    if (action === 'leave') {
113	      focusHeading.current = true;
114	      controller.leave();
115	    } else if (action === 'load' && pendingTransfer.current) {
116	      const transfer = pendingTransfer.current;
117	      pendingTransfer.current = null;
118	      setDraft(transfer.setup);
119	      controller.load(transfer);
120	    }
121	  }
122	
123	  function cancel(): void {
124	    pendingTransfer.current = null;
125	    setConfirmation(null);
126	  }
127	
128	  function exportJson(): void {
129	    const text = controller.exportTournament(draft);
130	    if (!text) {
131	      onAnnouncement('Tournament JSON is too large.');
132	      return;
133	    }
134	    setJson(text);
135	    onAnnouncement('Tournament exported to JSON box.');
136	  }
137	
138	  return (
139	    <section className="tournament-screen" aria-labelledby="tournament-heading">
140	      <h2 id="tournament-heading" ref={headingRef} tabIndex={-1}>
141	        Tournament
142	      </h2>
