144	        <TournamentPlay
145	          tournament={tournament}
146	          game={controller.session.game}
147	          generation={controller.session.generation}
148	          board={board}
149	          startButton={startButton}
150	          backButton={backButton}
151	          onActivate={controller.activate}
152	          onStartTurn={() => {
153	            focusBoard.current = true;
154	            controller.startCurrentTurn();
155	          }}
156	          onNextTurn={() => {
157	            focusStart.current = true;
158	            controller.advanceTurn();
159	          }}
160	          onNextMatch={() => {
161	            focusStart.current = true;
162	            controller.advanceMatch();
163	          }}
164	          onLeave={() => setConfirmation('leave')}
165	          onBack={onBack}
166	        />
167	      ) : (
168	        <TournamentSetup draft={draft} onChange={setDraft} onStart={start} onBack={onBack} />
169	      )}
170	      <section className="tournament-transfer" aria-labelledby="tournament-json-heading">
171	        <h3 id="tournament-json-heading">Tournament JSON</h3>
172	        <label htmlFor="tournament-json">Tournament JSON</label>
173	        <textarea
174	          id="tournament-json"
175	          className="control"
176	          rows={8}
177	          maxLength={65_536}
178	          value={json}
179	          onChange={(event) => setJson(event.currentTarget.value)}
180	        />
181	        <div className="tournament-actions">
182	          <button type="button" className="control" onClick={exportJson}>
183	            Export tournament
184	          </button>
185	          <button type="button" className="control" onClick={requestLoad}>
186	            Load tournament
187	          </button>
188	        </div>
189	      </section>
190	      <TournamentHistory
191	        available={controller.history.available}
192	        records={controller.history.records}
193	      />
194	      <dialog ref={dialog} className="tournament-dialog" onCancel={cancel}>
195	        <p>
196	          {confirmation === 'leave'
197	            ? 'Leave this unfinished tournament? Its bracket won’t be saved.'
198	            : 'Load this tournament and leave the current tournament?'}
199	        </p>
200	        <div className="tournament-actions">
201	          <button
202	            ref={keepButton}
203	            type="button"
204	            className="control"
205	            onClick={() => {
206	              dialog.current?.close();
207	              cancel();
208	            }}
209	          >
210	            Keep playing
211	          </button>
212	          <button type="button" className="control" onClick={confirm}>
213	            {confirmation === 'leave' ? 'Leave' : 'Load tournament'}
214	          </button>
215	        </div>
216	      </dialog>
217	    </section>
218	  );
219	}
